1	import { EventEmitter } from 'node:events';
2	import { ModelClient } from '../clients/ModelClient.js';
3	import { ShellEngine } from './ShellEngine.js';
4	import { Renderer } from '../ui/Renderer.js';
5	import type { SovereignConfig } from '../config/SovereignConfig.js';
6	import type { Result, EngineOutput } from '../core/models.js';
7	import { readFileSync, existsSync } from 'fs';
8	import { join } from 'path';
9	import { tmpdir } from 'os';
10	import { createLogger } from "../utils/logger.js";
11	import { SovereignEye } from '../utils/SovereignEye.js';
12	
13	const logger = createLogger('VisionEngine');
14	
15	export interface VisionParams {
16	    intent: 'chroma' | 'eye' | 'generic';
17	    target?: string; // process name or file path
18	    prompt?: string;
19	    modelOverride?: string;
20	}
21	
22	/**
23	 * VisionEngine Ã¢â‚¬â€ Multimodal observation substrate.
24	 * Implements SoverignEye (system-wide viewing) and Chromanumber (color/line mapping).
25	 */
26	export class VisionEngine extends EventEmitter {
27	    private static instance: VisionEngine;
28	    private readonly client: ModelClient;
29	    private readonly shell: ShellEngine;
30	    private readonly eye: SovereignEye;
31	
32	    private static initialized = false;
33	
34	    public static getInstance(config: SovereignConfig, renderer: Renderer): VisionEngine {
35	        if (!this.instance) {
36	            if (!config || !renderer) {
37	                throw new Error("VisionEngine requires config on first initialization");
38	            }
39	            this.instance = new VisionEngine(config, renderer);
40	            this.initialized = true;
41	        }
42	        return this.instance;
43	    }
44	
45	    public static isInitialized(): boolean {
46	        return this.initialized;
47	    }
48	
49	    private constructor(
50	        private readonly config: SovereignConfig,
51	        private readonly renderer: Renderer
52	    ) {
53	        super();
54	        this.client = new ModelClient(config);
55	        this.shell = new ShellEngine(renderer);
56	        this.eye = new SovereignEye('vision-engine');
57	        
58	        // Proxy SovereignEye captures to VisionEngine listeners (Switchboard)
59	        this.eye.on('capture', (res) => this.emit('capture', res));
60	    }
61	
62	    async observe(params: VisionParams): Promise<Result<EngineOutput>> {
63	        const screenshotPath = join(tmpdir(), `POG2_obs_${Date.now()}.png`);
64	
65	        // 1. Capture State (SoverignEye)
66	        if (params.intent === 'eye' || params.intent === 'chroma') {
67	            this.renderer.info('Capturing system state via SoverignEye...');
68	            const captureRes = await this.eye.capture({ type: 'window', target: params.target || 'POG2' });
69	            if (!captureRes.ok) return captureRes as any;
70	        }
71	
72	        const imagePath = params.target && existsSync(params.target)
73	            ? params.target
74	            : screenshotPath;
75	
76	        if (!existsSync(imagePath)) {
77	            return { ok: false, error: new Error(`Image not found for vision analysis: ${imagePath}`) };
78	        }
79	
80	        // 2. Multimodal Analysis
81	        const base64Image = readFileSync(imagePath).toString('base64');
82	        const modelPrompt = this.buildVisionPrompt(params);
83	
84	        const result = await this.client.call({
85	            model: params.modelOverride ?? this.config.visionModel,
86	            prompt: modelPrompt,
87	            images: [base64Image]
88	        });
89	
90	        if (!result.ok) return result as any;
91	
92	        return {
93	            ok: true,
94	            value: {
95	                output: result.value.response,
96	                data: {
97	                    intent: params.intent,
98	                    model: this.config.visionModel,
99	                    source: imagePath
100	                }
101	            }
102	        };
