694	                if (/^\d+$/.test(input)) {
695	                    url += `&id=${input}`;
696	                } else {
697	                    url += `&name=${encodeURIComponent(input)}`;
698	                }
699	
700	                const resp = await fetch(url);
701	                if (!resp.ok) {
702	                    throw new Error(`Enrich API failed: ${resp.status}`);
703	                }
704	                const data = await resp.json();
705	
706	                // Update Telemetry target
707	                document.getElementById('target-name').textContent = data.name || data.queryName || input;
708	                if (data.cacheData) {
