726	            if (!cardContainer) return;
727	
728	            const isItem = type === 'item' || data.role === 'ITEM';
729	            const labelWho = isItem ? 'WHAT' : 'WHO';
730	            const labelWhat = isItem ? 'DETAIL' : 'WHAT';
731	            const labelWhere = isItem ? 'SOURCE' : 'WHERE';
732	            const labelWhy = isItem ? 'USAGE' : 'WHY';
733	
734	            const who = data.name || 'Unknown Entity';
735	            const role = data.role || type.toUpperCase();
736	            let what = data.extract || data.description || 'No descriptive context recorded in local RuneScape cache.';
737	            const where = data.location || (data.cacheData && data.cacheData.location) || 'Fringe Substrate / Coordinates Unresolved';
738	            let why = data.strategy || data.combatRotation || 'Standard behavioral routing. Proceed with typical PvME capability rotations.';
739	
740	            if (isItem && data.cacheData) {
741	                const itemData = data.cacheData;
742	                const raw = itemData.raw || {};
743	                
744	                let details = [];
745	                if (raw.value !== undefined) details.push(`Value: ${raw.value.toLocaleString()} gp`);
746	                if (itemData.isEquippable) details.push(`Equippable (Slot: ${itemData.equipSlotId})`);
747	                if (raw.category) details.push(`Category: ${raw.category}`);
748	                
749	                if (details.length > 0) {
750	                    what = details.join(' | ') + '<br>' + what;
751	                }
752	
753	                if (itemData.actions && itemData.actions.length > 0) {
754	                    why = `Actions: ${itemData.actions.filter(a => a).join(', ')}`;
755	                }
756	            }
