764	                    <div><strong>${labelWhat}:</strong> <span style="color: #ccc; font-style: italic;">${what}</span></div>
765	                    <div><strong>${labelWhere}:</strong> <span>${where}</span></div>
766	                    <div><strong>${labelWhy}:</strong> <span style="color: var(--adrenaline-orange);">${why}</span></div>
767	                    ${data.url ? `<a href="${data.url}" target="_blank" class="enrich-wiki-link">Open Wiki Page ↗</a>` : ''}
