786	
787	                const pcs = new BABYLON.PointsCloudSystem("pcs", 1, scene);
788	                const pos = md.positions;
789	                pcs.addPoints(pos.length / 3, (p, i) => {
790	                    p.position = new BABYLON.Vector3(pos[i * 3], pos[i * 3 + 1], pos[i * 3 + 2]);
