821	        function executeSlotAbility(index) {
822	            const slotData = activeSlots[index];
823	            if (!slotData || !slotData.abilityId) return;
824	
825	            const abilityId = slotData.abilityId;
826	            const cd = state.cooldowns[abilityId] || 0;
827	            if (cd > 0) return;
828	
829	            const adrenCost = slotData.adrenalineCost || 0;
830	            const adrenReq = slotData.adrenalineThreshold || 0;
831	            if (state.adrenaline < adrenReq) {
832	                log(`Insufficient Adrenaline for ${slotData.abilityName}`, 'system');
833	                return;
834	            }
835	
836	            state.adrenaline = Math.max(0, state.adrenaline - adrenCost);
837	            state.cooldowns[abilityId] = slotData.cooldownTotal || 3;
838	
839	            const tier = slotData.tier || 'basic';
840	            const style = slotData.style || 'melee';
841	
842	            log(`Executed: ${slotData.abilityName}`, tier, style);
843	            emitGhostSplat(tier === 'ultimate' ? 'crit' : 'damage', Math.floor(Math.random() * 500) + 100, tier, style);
844	            updateUI();
845	        }
