852	        async function initScene() {
853	            scene = new BABYLON.Scene(engine);
854	            scene.clearColor = new BABYLON.Color4(0.02, 0.02, 0.03, 1);
855	
856	            const camera = new BABYLON.ArcRotateCamera("camera", -Math.PI / 2, Math.PI / 2.5, 250, BABYLON.Vector3.Zero(), scene);
857	            camera.attachControl(canvas, true);
858	            camera.wheelPrecision = 20;
859	
860	            const light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
861	            light.intensity = 0.8;
862	
863	            // Load Model (Kit 31149)
864	            try {
865	                const res = await fetch('/models/kit_31149.json');
866	                const md = await res.json();
867	                const pcs = new BABYLON.PointsCloudSystem("pcs", 1, scene);
868	                const pos = md.positions;
869	                pcs.addPoints(pos.length / 3, (p, i) => {
870	                    p.position = new BABYLON.Vector3(pos[i * 3], pos[i * 3 + 1], pos[i * 3 + 2]);
871	                    p.color = new BABYLON.Color4(0.3, 0.6, 0.9, 1);
872	                });
873	                await pcs.buildMeshAsync();
874	                camera.target = pcs.mesh.getBoundingInfo().boundingBox.center;
875	                currentPCS = pcs;
876	            } catch (e) { console.warn("Model fetch failed, using fallback."); }
877	
878	            return scene;
