881	        // ─── Ghost Splats ───────────────────────────────────────────────
882	        function emitGhostSplat(type, value, tier, style = 'ranged') {
883	            const id = `splat_${Date.now()}`;
884	            const size = tier === 'ultimate' ? 60 : tier === 'enhanced' ? 45 : 30;
885	            const color = tier === 'ultimate' ? '#ffaa00' : COLORS[style] || '#44ff44';
886	
887	            const plane = BABYLON.MeshBuilder.CreatePlane(id, { size }, scene);
888	            plane.position = new BABYLON.Vector3((Math.random() - 0.5) * 80, 130 + Math.random() * 40, -20);
889	            plane.billboardMode = BABYLON.Mesh.BILLBOARDMODE_ALL;
890	
891	            const tex = new BABYLON.DynamicTexture(`tex_${id}`, { width: 256, height: 128 }, scene, false);
892	            tex.hasAlpha = true;
893	            const ctx = tex.getContext();
894	            ctx.clearRect(0, 0, 256, 128);
895	            ctx.font = `bold ${tier === 'ultimate' ? 80 : 64}px Inter`;
896	            ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
897	            ctx.lineWidth = 6; ctx.strokeStyle = '#000';
898	            ctx.strokeText(value, 128, 64);
