906	            mat.useAlphaFromDiffuseTexture = true;
907	            plane.material = mat;
908	
909	            const animate = () => {
910	                plane.position.y += 0.8;
911	                mat.alpha -= 0.015;
912	                if (mat.alpha <= 0) { plane.dispose(); return; }
913	                requestAnimationFrame(animate);
