963	                                document.getElementById('rotation-display').textContent = payload.activeRotation;
964	                            }
965	
966	                            // Target HP
967	                            if (payload.targetHp !== undefined) {
968	                                document.getElementById('target-hp').textContent = payload.targetHp.toLocaleString();
969	                            }
970	
971	                            // Kernel Phase
972	                            if (payload.kernelPhase) {
973	                                document.getElementById('kernel-phase').textContent = payload.kernelPhase;
974	
975	                                // Volatility mapping
