async function loadRegion() {
  const rx = document.getElementById('rx').value;
  const ry = document.getElementById('ry').value;
  const filename = `ms_${rx}_${ry}.json`;
  document.getElementById('status').textContent = `Loading ${filename}...`;

  try {
    const url = `${window.location.origin}/world/${filename}`;
    const resp = await fetch(url);
    if (!resp.ok) {
      document.getElementById('status').textContent = `${filename} not found in /world/ (${resp.status})`;
      return;
    }
    const data = await resp.json();
    ingestData(data);
  } catch (err) {
    document.getElementById('status').textContent = `Error: ${err.message}`;
  }
}

// Tooltip
canvas.addEventListener('mousemove', (e) => {
  if (!regionData) return;
  const rect = canvas.getBoundingClientRect();
  const scale = parseInt(document.getElementById('scale').value);
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;
  const lx = Math.floor(mx / scale);
  const ly = 63 - Math.floor(my / scale);

  if (lx < 0 || lx >= 64 || ly < 0 || ly >= 64) {
    tooltip.style.display = 'none';
    return;
  }

  const wx = worldOriginX + lx;
  const wy = worldOriginY + ly;
  const key = `${wx}_${wy}`;
  const tile = matrixMap[key];

  let html = `<b>[${wx}, ${wy}]</b> local [${lx}, ${ly}]<br>`;

  if (tile) {
    const walkIcon = tile.walkable ? '✅' : '🚫';
    html += `Surface: <b>${tile.surfaceType || 'terrain'}</b> ${walkIcon}<br>`;
    html += `Flags: <b>0x${(tile.sourceFlags || 0).toString(16)}</b><br>`;

    if (tile.edges) {
      const e = tile.edges;
      const arrow = (blocked) => blocked ? '<span style="color:#ff3030">■</span>' : '<span style="color:#2a8a62">□</span>';
      html += `<span class="edge-label">`;
      html += `N:${arrow(e.northBlocked)} S:${arrow(e.southBlocked)} `;
      html += `E:${arrow(e.eastBlocked)} W:${arrow(e.westBlocked)}`;
      html += `</span><br>`;
    }
  } else {
    html += '<i style="color:#555">No data</i>';
  }

  // Entities at this tile
  const tileEnts = entities.filter(en => en.x === wx && en.y === wy);
  if (tileEnts.length > 0) {
    html += `<br><b>${tileEnts.length} entity(s):</b><br>`;
    for (const en of tileEnts.slice(0, 3)) {
      const color = en.type === 'npc' ? '#51ffff' : '#b080ff';
      html += `• <span style="color:${color}">${en.name || en.id}</span> (${en.type})<br>`;
    }
  }

  tooltip.innerHTML = html;
  tooltip.style.display = 'block';
  tooltip.style.left = (e.clientX + 14) + 'px';
  tooltip.style.top = (e.clientY + 14) + 'px';
});

